beforeExample:
package org.eclipse.jdt.internal.ui.text.template.contentassist;

import org.eclipse.jdt.internal.corext.template.java.CompilationUnitContext;
import org.eclipse.jdt.internal.corext.template.java.MultiVariableGuess;

class TemplateProposal {
    Object fContext;

    void apply() {
        MultiVariableGuess guess = fContext instanceof CompilationUnitContext ? ((CompilationUnitContext) fContext).getMultiVariableGuess() : null;
        CompilationUnitContext directUsage = (CompilationUnitContext) fContext;
    }
}

afterExample:
package org.eclipse.jdt.internal.ui.text.template.contentassist;

import org.eclipse.jdt.internal.corext.template.java.JavaContext;
import org.eclipse.jdt.internal.corext.template.java.MultiVariableGuess;

class TemplateProposal {
    Object fContext;

    void apply() {
        MultiVariableGuess guess = fContext instanceof JavaContext ? ((JavaContext) fContext).getMultiVariableGuess() : null;
        JavaContext directUsage = (JavaContext) fContext;
    }
}

